<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Room extends Model{protected $fillable=['number','room_category_id','floor','status'];public function category(){return $this->belongsTo(RoomCategory::class,'room_category_id');}public function tenants(){return $this->hasMany(Tenant::class);}public function maintenances(){return $this->hasMany(Maintenance::class);}public function importRows(){return $this->hasMany(ImportRow::class);}public function activeTenant(){return $this->hasOne(Tenant::class)->where('active',true);}}
